(x, y, t) => {
  const cx = 240, cy = 120;
  const src = [
    [120 + Math.sin(t*0.7)*80, 60 + Math.cos(t*0.5)*40, 0.07, 2.1, 0.6],
    [360 + Math.cos(t*0.5)*80, 60 + Math.sin(t*0.6)*40, 0.09, 1.8, 0.7],
    [240 + Math.sin(t*0.4+2)*120, 120 + Math.cos(t*0.6+1)*80, 0.06, 2.4, 0.5],
    [100 + Math.cos(t*0.8+1)*60, 180 + Math.sin(t*0.3)*50, 0.08, 1.9, 0.6],
    [380 + Math.sin(t*0.6+3)*70, 180 + Math.cos(t*0.7+2)*50, 0.1, 2.2, 0.5],
    [240 + Math.cos(t*0.35)*150, 40 + Math.sin(t*0.45)*30, 0.05, 2.6, 0.4]
  ];
  let act = 0, inh = 0, det = 0;
  for (let i = 0; i < src.length; i++) {
    const [sx, sy, freq, spd, w] = src[i];
    const d = Math.sqrt((x-sx)**2 + (y-sy)**2);
    const wave = Math.sin(d*freq - t*spd);
    act += wave * w;
    inh += Math.sin(d*freq*0.7 + t*spd*0.5 + i) * w * 0.6;
    det += Math.sin(d*freq*1.5 - t*spd*1.3 + i*1.7) * w * 0.25;
  }
  const diag1 = Math.sin((x+y)*0.12 + t*0.9) * 0.3;
  const diag2 = Math.sin((x-y)*0.1 - t*1.2) * 0.3;
  const cross = Math.sin(x*0.08)*Math.sin(y*0.08) * 0.2;
  const dist = Math.sqrt((x-cx)**2 + (y-cy)**2);
  const ang = Math.atan2(y-cy, x-cx);
  const rad = Math.sin(dist*0.035 - t*1.3);
  const spir = Math.sin(ang*5 + dist*0.02 - t*0.8);
  const moire = Math.sin(x*0.15)*Math.sin(y*0.15)*Math.sin((x+y)*0.08+t)*0.15;
  const totalAct = act + diag1 + cross;
  const totalInh = inh + diag2 + moire;
  let reaction = totalAct - totalInh*0.7 + (rad+spir*0.4)*0.5 + det;
  for (let j = 0; j < 2; j++) reaction = Math.tanh(reaction*1.8);
  const edge = Math.tanh((220 - dist)*0.02);
  const vign = 1 - dist*0.0015;
  const v = reaction*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.5+0.5;
  const pal1 = [[8,15,58],[22,72,112],[45,148,135],[175,195,80],[225,165,55],[195,85,50],[120,35,85],[8,15,58]];
  const pal2 = [[10,12,48],[35,50,120],[80,140,160],[160,200,140],[230,190,90],[210,120,70],[100,40,100],[10,12,48]];
  const pal = hueShift < 0.5 ? pal1 : pal2;
  const hf = hueShift < 0.5 ? hueShift*2 : (1-hueShift)*2;
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const detail = Math.abs(det)*0.12;
  const lum = (0.82 + Math.sin(reaction*Math.PI)*0.18) * vign * edge;
  return [
    Math.min(255, Math.max(0, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f + detail*80)*lum))|0,
    Math.min(255, Math.max(0, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f + detail*60)*lum))|0,
    Math.min(255, Math.max(0, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f + detail*100)*lum))|0
  ];
}
